package com.fixmer.genesis.supervisor;
import javax.swing.*;import java.awt.*;import java.awt.event.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;
/** Small named emergency window; ordinary startup still uses the in-game panel. */
public final class RecoveryBootstrap92 {
 private static final AtomicBoolean shown=new AtomicBoolean();
 private RecoveryBootstrap92(){}
 public static void open(Path config){if(GraphicsEnvironment.isHeadless()||!shown.compareAndSet(false,true))return;SwingUtilities.invokeLater(()->{try{new Window(config);}catch(Exception failed){shown.set(false);System.err.println("RECOVERY92_UNAVAILABLE");}});}
 public static void main(String[] args){try{
  Path config=null;String action="",ticket="",revision="";boolean status=false;
  for(String arg:args){if(arg.startsWith("--config="))config=Path.of(arg.substring(9));else if(arg.equals("--status"))status=true;else if(arg.startsWith("--action="))action=arg.substring(9);else if(arg.startsWith("--ticket="))ticket=arg.substring(9);else if(arg.startsWith("--revision="))revision=arg.substring(11);else throw new IllegalArgumentException();}
  if(config==null)throw new IllegalArgumentException();
  if(status||!action.isEmpty()){var c=new RecoveryConnection92(config);Properties p=c.status();if(!action.isEmpty()){Properties reviewed=new Properties();reviewed.setProperty("ticket",ticket);reviewed.setProperty("revision",revision);if(!c.decide(reviewed,action))throw new java.io.IOException("RECOVERY92_STALE");System.out.println("RECOVERY92_ACCEPTED");}else{for(String key:ListKeys.KEYS)System.out.println(key+"="+p.getProperty(key,""));}return;}
  if(GraphicsEnvironment.isHeadless())throw new IllegalArgumentException();open(config);
 }catch(Exception failed){System.err.println("RECOVERY92_UNAVAILABLE_OR_STALE: no offline mutation performed");System.exit(2);}}
 private static class ListKeys{static final String[] KEYS={"schema","state","busy","ticket","revision","launch","used","error","phase","mod","version","previous","retryAllowed"};}
 private static final class Window {
  final JFrame frame=new JFrame("Genesis — Восстановление локального мода");final JTextArea text=new JTextArea();final JButton restore=new JButton("Восстановить прежний JAR"),retry=new JButton("Повторить текущую версию"),refresh=new JButton("Обновить"),close=new JButton("Оставить игру закрытой");
  final RecoveryConnection92 client;final ScheduledExecutorService io=Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"genesis-recovery92-window");t.setDaemon(true);return t;});volatile Properties current=new Properties();volatile boolean sending;boolean finished;
  Window(Path config)throws Exception{client=new RecoveryConnection92(config);frame.setDefaultCloseOperation(WindowConstants.DO_NOTHING_ON_CLOSE);frame.addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){if(!sending)action("CLOSE");}});
   text.setEditable(false);text.setLineWrap(true);text.setWrapStyleWord(true);text.setMargin(new Insets(14,14,14,14));text.setFont(new Font(Font.DIALOG,Font.PLAIN,14));frame.add(new JScrollPane(text),BorderLayout.CENTER);JPanel buttons=new JPanel(new GridLayout(2,2,8,8));buttons.setBorder(BorderFactory.createEmptyBorder(8,10,10,10));for(JButton b:new JButton[]{restore,retry,refresh,close})buttons.add(b);frame.add(buttons,BorderLayout.SOUTH);
   restore.addActionListener(e->action("RESTORE"));retry.addActionListener(e->action("RETRY"));refresh.addActionListener(e->action("REFRESH"));close.addActionListener(e->action("CLOSE"));frame.setSize(590,360);frame.setMinimumSize(new Dimension(440,280));frame.setLocationRelativeTo(null);frame.setVisible(true);restore.setEnabled(false);retry.setEnabled(false);close.setEnabled(false);refresh.setEnabled(false);text.setText("Проверяем владельца и завершение игры…");io.scheduleWithFixedDelay(this::poll,0,1,TimeUnit.SECONDS);
  }
  void poll(){if(finished||sending)return;try{Properties p=client.status();SwingUtilities.invokeLater(()->update(p));}catch(Exception unavailable){SwingUtilities.invokeLater(()->{text.setText("Контроллер недоступен или сменился. Файлы не изменялись этим окном.\nЗакрой это окно; не восстанавливай JAR в работающем профиле.");restore.setEnabled(false);retry.setEnabled(false);refresh.setEnabled(false);close.setText("Закрыть окно");close.setEnabled(true);current=new Properties();});}}
  void update(Properties p){if(finished||sending)return;current=p;String state=p.getProperty("state","");if(state.equals("RUNNING")){finish();return;}
   boolean eligible=state.equals("RECOVERY_REQUIRED")&&!Boolean.parseBoolean(p.getProperty("busy"))&&!Boolean.parseBoolean(p.getProperty("used"));
   text.setText(eligible?"Minecraft завершился до подтверждения установки. Управляемая JVM и известные дочерние процессы завершены.\n\nМод: "+p.getProperty("mod","—")+"\nТекущая версия: "+p.getProperty("version","—")+"\nПрежняя версия: "+(p.getProperty("previous","").isEmpty()?"мод отсутствовал":p.getProperty("previous"))+"\n\nВозвращается только JAR. Данные мира не откатываются. После восстановления мир автоматически не откроется.\n\nПри бездействии контроллер завершится через 10 минут, сохранив журнал.":"Игра или контроллер ещё занят. Восстановление сейчас недоступно; файлы не меняем.");
   if(p.getProperty("phase","").equals("RESTORED_REVIEW"))text.append("\n\nПрежний JAR уже восстановлен, но игра снова завершилась. Другие файлы автоматически не меняем. Сохрани журнал запуска.");
   if(p.getProperty("error","").equals("PROFILE92_IN_USE"))text.append("\n\nПрофиль занят или его блокировка недоступна. Закрой другой клиент MaRed обычным способом, затем обнови сведения.");
   else if(!p.getProperty("error","").isEmpty())text.append("\n\nПроверка не прошла. Обнови сведения; если ошибка повторится, сохрани диагностику.");
   boolean choice=Set.of("CHOICE_REQUIRED","RESTORE_REQUESTED").contains(p.getProperty("phase",""));restore.setEnabled(eligible&&choice);retry.setEnabled(eligible&&choice&&Boolean.parseBoolean(p.getProperty("retryAllowed")));refresh.setEnabled(eligible);close.setEnabled(true);close.setText(eligible?"Оставить игру закрытой":"Закрыть окно");
  }
  void action(String action){if(sending)return;if(current.isEmpty()||action.equals("CLOSE")&&!current.getProperty("state","").equals("RECOVERY_REQUIRED")){finish();return;}Properties review=new Properties();review.putAll(current);
   if(!Set.of("CLOSE","REFRESH").contains(action)){String warning=action.equals("RESTORE")?"Вернуть прежний JAR и запустить игру до меню?\nМир не будет восстановлен из копии. Совместимость данных неизвестна.":"Повторить один запуск с текущим JAR до меню?\nЭто не подтверждает исправность мода или мира.";if(JOptionPane.showConfirmDialog(frame,warning,"Genesis — Подтверждение",JOptionPane.OK_CANCEL_OPTION,JOptionPane.WARNING_MESSAGE)!=JOptionPane.OK_OPTION)return;}
   sending=true;for(JButton b:new JButton[]{restore,retry,refresh,close})b.setEnabled(false);text.setText("Запрос отправляется владельцу. Ничего не запускаем из этого окна…");io.execute(()->{try{boolean accepted=client.decide(review,action);SwingUtilities.invokeLater(()->{sending=false;if(accepted&&action.equals("CLOSE")){finish();return;}text.setText(accepted?"Запрос принят. Ждём результата; повторно действие не отправляем.":"Состояние изменилось. Обнови сведения и проверь выбор снова.");});}catch(Exception error){SwingUtilities.invokeLater(()->{sending=false;if(action.equals("CLOSE")){finish();return;}text.setText("Связь потеряна. Результат запроса неизвестен; повторно автоматически не отправляем.");});}});
  }
  void finish(){if(finished)return;finished=true;io.shutdownNow();frame.dispose();shown.set(false);}
 }
}
